-- Migration: carga inicial das figurinhas do álbum AABB 2026
-- Fonte: Album_AABB_2026_Corrigido.pdf + arquivo JSON de OCR.
-- Total: 345 registros.
-- Atenção: os endpoints de imagem foram copiados do JSON e podem ser temporários.

BEGIN;

ON CONFLICT (id) DO UPDATE SET
    nome_jogador = EXCLUDED.nome_jogador,
    img_jogador  = EXCLUDED.img_jogador,
    equipe       = EXCLUDED.equipe,
    categoria    = EXCLUDED.categoria;

COMMIT;
